node --input-type=module -e "
import { loadEnv, botToken, AVA_CHANNELS } from './src/config.mjs';
import { makeFetchJson } from './src/discordApi.mjs';

const TARGET = '1533619429953241180';
const BAN_BOATS = '1533603278816936168';

const env = await loadEnv();
const tok = botToken(env);
if (!tok) { console.error('no token'); process.exit(1); }
const fj = makeFetchJson(tok);

async function tryFetch(channelId) {
  try {
    const msg = await fj('/channels/' + channelId + '/messages/' + TARGET);
    return msg;
  } catch (e) {
    return { _err: e.message, channelId };
  }
}

// Try Ban boats thread first
let msg = await tryFetch(BAN_BOATS);
if (msg._err) {
  console.log('Ban boats miss:', msg._err);
  // Try around Ban boats for nearby
} else {
  console.log('FOUND in Ban boats thread');
}

if (msg._err) {
  // Try other known channels
  const ids = [...new Set([
    BAN_BOATS,
    ...Object.values(AVA_CHANNELS).filter(Boolean).map(String),
  ])];
  for (const id of ids) {
    if (id === BAN_BOATS) continue;
    const r = await tryFetch(id);
    if (!r._err) { msg = r; console.log('FOUND in', id); break; }
  }
}

if (msg._err) {
  console.log(JSON.stringify({ miss: true, err: msg._err }, null, 2));
  process.exit(2);
}

const chId = msg.channel_id;
console.log(JSON.stringify({
  id: msg.id,
  channel_id: chId,
  author: { id: msg.author?.id, username: msg.author?.username, global: msg.author?.global_name, bot: msg.author?.bot },
  content: msg.content,
  timestamp: msg.timestamp,
  referenced: msg.referenced_message ? { id: msg.referenced_message.id, author: msg.referenced_message.author?.username, content: msg.referenced_message.content?.slice(0,200) } : null,
  mentions: (msg.mentions||[]).map(m => ({ id: m.id, username: m.username })),
  reactions: msg.reactions,
}, null, 2));

// Nearby context
const around = await fj('/channels/' + chId + '/messages?around=' + TARGET + '&limit=15');
console.log('---NEARBY---');
for (const m of around.reverse ? around.slice().reverse() : around) {
  console.log([m.id, m.author?.username, (m.content||'').slice(0,180).replace(/\\n/g,' / ')].join(' | '));
}

// Channel info
try {
  const ch = await fj('/channels/' + chId);
  console.log('---CHANNEL---');
  console.log(JSON.stringify({ id: ch.id, name: ch.name, type: ch.type, parent_id: ch.parent_id }, null, 2));
} catch (e) { console.log('ch err', e.message); }
"

